        System.Collections.Generic.List<object[]> artikujt = new System.Collections.Generic.List<object[]>();
  int cnt = 0;
 double totalimetvshkursi = 0;
 double totalipatvshkursi = 0;
private void ReportFooter_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 if (artikujt.Count == 0)
                ReportFooter.Visible = false;
}

private void xrTable5_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 int i = 0;
            if (artikujt.Count > 0)
            {
                xrTable5.Rows.Clear();
                foreach (object[] obj in artikujt)
                {
                    XRTableRow rr = new XRTableRow();
                    rr.HeightF = 25f;

                    XRTableCell pershkrimi = new XRTableCell();
                    pershkrimi.WidthF = 110f;
                    pershkrimi.Name = "pershkrimi" + i.ToString();
                    pershkrimi.Text = obj[0].ToString();
                    rr.Cells.Add(pershkrimi);

                    XRTableCell serial = new XRTableCell();
                    serial.WidthF = 80f;
                    serial.Name = "NrSerial" + i.ToString();
                    serial.Text = obj[1].ToString();
                    rr.Cells.Add(serial);

                    XRTableCell afatGarancie = new XRTableCell();
                    afatGarancie.WidthF = 10f;
                    afatGarancie.Name = "afatGarancie" + i.ToString();
                    afatGarancie.Text = String.Format("{0:#,#}", obj[2]);
                    rr.Cells.Add(afatGarancie);

                    XRTableCell llojGarancie = new XRTableCell();
                    llojGarancie.Name = "llojGarancie" + i.ToString();
                    llojGarancie.Text = obj[3].ToString();
                    rr.Cells.Add(llojGarancie);

                    xrTable5.Rows.Insert(i, rr);
                    i++;
                }
            }
}

private void xrTable3_PrintOnPage(object sender, DevExpress.XtraReports.UI.PrintOnPageEventArgs e) {
  if ((ReportFooter.Visible) && (e.PageIndex != e.PageCount - 2)) 
                xrTable3.Visible = false;
            else if ((ReportFooter.Visible == false) && (e.PageIndex != e.PageCount - 1)) 
                xrTable3.Visible = false;
}

private void xrLabel62_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (GetCurrentColumnValue("AfatGarancie") != null && GetCurrentColumnValue("AfatGarancie").ToString() != "" && decimal.Parse(GetCurrentColumnValue("AfatGarancie").ToString()) != 0 && GetCurrentColumnValue("LlojGarancie") != null && GetCurrentColumnValue("LlojGarancie").ToString() != "")
            {
                object[] obj = new object[4];
                obj[0] = GetCurrentColumnValue("PERSHKRIMI");
                if (GetCurrentColumnValue("serialart") != null)
                    obj[1] = GetCurrentColumnValue("serialart");
                else obj[1] = "";
                if (GetCurrentColumnValue("AfatGarancie") != null)
                    obj[2] = GetCurrentColumnValue("AfatGarancie");
                else obj[2] = "";
                if (GetCurrentColumnValue("LlojGarancie") != null)
                    obj[3] = GetCurrentColumnValue("LlojGarancie");
                else obj[3] = "";

                artikujt.Add(obj);
            }
}

private void xrTableCell1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 cnt++;
            xrTableCell1.Text = cnt.ToString();
            totalimetvshkursi += Convert.ToDouble(GetCurrentColumnValue("VLEFTAMETVSH"));
            totalipatvshkursi += Convert.ToDouble(GetCurrentColumnValue("VLEFTAMETVSH"));
}
